/* mindset-tile.js v1.0 (Oct 20, 2026)
   ONE definition of how a Mindset Training tile is drawn from saved words and
   pictures. The Mindset Training deck and the Card Maker both load this file,
   so the two can never drift apart. Every measurement was taken from the
   Meditation and Gratitude tiles (531 x 819), scaled to a 344 px tile.
   A card row looks like {name, category, picture_size, tiles:[{caption, text,
   order:'words'|'pic', picture}]}. Never redraw this elsewhere. */
(function(){
var K=344/531;
var CATS={"physical": {"label": "Physical Health", "band": "#edd2d2", "w": 78, "h": 112, "x": 26, "y": 9, "img": "data:image/png;base64,"}, "recreational": {"label": "Recreational Health", "band": "#fedbc7", "w": 117, "h": 101, "x": 16, "y": 17, "img": "data:image/png;base64,"}, "purpose": {"label": "Sense of Purpose", "band": "#ffecec", "w": 77, "h": 107, "x": 26, "y": 16, "img": "data:image/png;base64,"}, "emotional": {"label": "Emotional Health", "band": "#e5ebff", "w": 93, "h": 113, "x": 18, "y": 11, "img": "data:image/png;base64,"}, "environmental": {"label": "Environmental Health", "band": "#cdeced", "w": 131, "h": 110, "x": 9, "y": 11, "img": "data:image/png;base64,"}, "mental": {"label": "Mental Fitness", "band": "#fefde4", "w": 73, "h": 111, "x": 31, "y": 13, "img": "data:image/png;base64,"}};
var CSS='.mtile{container-type:inline-size;position:relative;width:100%;aspect-ratio:531/819;background:#fff;border:1px solid #9a9a96;border-radius:6.5%/4.2%;box-shadow:0 12px 34px rgba(31,42,68,.10);overflow:hidden;cursor:zoom-in;display:block}'+
'.mtin{--u:calc(100cqw/344);--pm:calc(var(--u)*30);height:100%;display:flex;flex-direction:column;color:#555a64;font-family:Lato,Calibri,Carlito,Arial,Helvetica,sans-serif;font-size:calc(var(--u)*13.6);line-height:1.3;text-align:left}'+
'.mthead{flex:none;height:calc(var(--u)*84);position:relative}.mthead img{position:absolute}'+
'.mttt{position:absolute;top:0;bottom:0;right:calc(var(--u)*12);display:flex;align-items:center;justify-content:center;font-family:"Source Serif 4",Georgia,serif;color:#4a4f5a;text-align:center;line-height:1.1}'+
'.mtcap{flex:none;text-align:center;font-size:calc(var(--u)*11.8);letter-spacing:calc(var(--u)*.5);text-transform:uppercase;color:#8d929c;padding-top:calc(var(--u)*13);height:calc(var(--u)*34)}'+
'.mtpic{flex:none;margin:calc(var(--u)*11) var(--pm) 0;display:flex;justify-content:center}'+
'.mtpic img{display:block;width:100%;max-height:calc(var(--u)*var(--ph,300));object-fit:contain;border-radius:calc(var(--u)*13)}'+
'.mtpic:last-child{margin-bottom:calc(var(--u)*30)}'+
'.mttxt{flex:1;min-height:0;padding:calc(var(--u)*13) calc(var(--u)*30) calc(var(--u)*14)}'+
'.mttxt p{margin:0 0 calc(var(--u)*7)}.mttxt ul{margin:0 0 calc(var(--u)*7);padding-left:calc(var(--u)*15)}.mttxt li{margin:0 0 calc(var(--u)*2)}'+
'.mttxt b{font-weight:700;color:#33373f}.mttxt.mtbig{font-size:calc(var(--u)*16.2)}';
function injectCss(){ if(document.getElementById('mt-css'))return; var s=document.createElement('style'); s.id='mt-css'; s.textContent=CSS; document.head.appendChild(s); }
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function inl(s){return esc(s).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/\*(.+?)\*/g,'<i>$1</i>');}
function md(t){var out='',ul=false;String(t||'').split('\n').forEach(function(l){var m=/^\s*-\s+(.*)$/.exec(l);
  if(m){if(!ul){out+='<ul>';ul=true;}out+='<li>'+inl(m[1])+'</li>';}else{if(ul){out+='</ul>';ul=false;}if(l.trim())out+='<p>'+inl(l.trim())+'</p>';}});
  if(ul)out+='</ul>';return out;}
function head(card){
  var c=CATS[card.category]||CATS.mental, nm=card.name||'', fs=nm.length<=12?24.5:(nm.length<=19?22.5:18.5);
  var icon='<img src="'+c.img+'" alt="" style="left:calc(var(--u)*'+(c.x*K).toFixed(1)+');top:calc(var(--u)*'+(c.y*K).toFixed(1)+');width:calc(var(--u)*'+(c.w*K).toFixed(1)+')">';
  var left=(c.x+c.w)*K+6;
  return '<div class="mthead" style="background:'+c.band+'">'+icon+'<div class="mttt" style="left:calc(var(--u)*'+left.toFixed(1)+');font-size:calc(var(--u)*'+fs+')">'+esc(nm)+'</div></div>';
}
/* i is the tile index, starting at 0 */
function tile(card,i){
  injectCss();
  var t=(card.tiles||[])[i]; if(!t) return '';
  var size=card.picture_size||card.pictureSize||86;
  /* words-first tiles share the space with their picture, so the picture is capped to what is left */
  var ph=300;
  if(t.order==='words'){var big=i===0,cpl=big?33:42,lh=big?21.1:17.7,lines=0,blocks=0;
    String(t.text||'').split('\n').forEach(function(l){if(l.trim()){blocks++;lines+=Math.max(1,Math.ceil(l.replace(/^\s*-\s+/,'').length/cpl));}});
    ph=Math.max(150,Math.min(300,531-(big?84:34)-(27+lines*lh+blocks*5)-11-30));}
  var pic=t.picture?'<div class="mtpic" style="--ph:'+ph.toFixed(0)+';--pm:calc(var(--u)*'+(344*(1-size/100)/2).toFixed(1)+')"><img src="'+esc((window.MT_PICS&&window.MT_PICS[t.picture])||t.picture)+'" alt=""></div>':'';
  var top=i===0?head(card):'<div class="mtcap">'+esc(t.caption)+'</div>';
  var txt='<div class="mttxt'+(i===0?' mtbig':'')+'">'+md(t.text)+'</div>';
  var body=(t.order==='words')?txt+pic:pic+txt;
  return '<div class="mtile"><div class="mtin">'+top+body+'</div></div>';
}
window.MT={CATS:CATS,tile:tile,md:md,catLabel:function(k){return (CATS[k]||{}).label||'';}};
})();
